def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f"Key not found: {key}")

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """

    if not keys:
        return list(self._items.values())

    results = []
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._items):
                raise IndexError("Index out of range: {0}".format(key))
            results.append(list(self._items.values())[key])
        elif isinstance(key, str):
            if key not in self._items:
                raise KeyError("Key not found: {0}".format(key))
            results.append(self._items[key])
        else:
            raise TypeError("Invalid key type: {0}".format(type(key).__name__))

    return results

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        for key, value in self._record.items():
            result[key] = value
    else:
        for key in keys:
            if isinstance(key, int):
                if key < 0 or key >= len(self._record):
                    raise IndexError("Out-of-bounds index specified")
                result[self._record.keys()[key]] = self._record.values()[key]
            elif isinstance(key, str):
                result[key] = self._record.get(key, None)
            else:
                raise TypeError("Invalid key type")
    return result

def pop_u16(self):
    """
    Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    return self.unpack('>H', 2)

def round_half_to_even(n):
    """
    Round half to even (also known as "bankers' rounding").

    :param n: The number to round.
    :return: The rounded number.
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number")

    if n % 1 == 0.5:
        return int(n) + (1 if n > 0 else -1)
    else:
        return round(n)

