def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    missing_digests = []
    unused_digests = []

    for file in manifest_files:
        with open(file, 'r') as f:
            manifest_content = f.read()
            required_digests = set()
            for line in manifest_content.splitlines():
                if 'digest' in line:
                    digest = line.split('=')[1].strip()
                    required_digests.add(digest)

            for digest in required_digests:
                if digest not in digests_used:
                    missing_digests.append(digest)

    for digest in digests_used:
        if digest not in required_digests:
            unused_digests.append(digest)

    return missing_digests, unused_digests

