def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, tuple):
            if expr[0] == '&':
                if expr[1] == ('|', expr[0], expr[2]):
                    return expr[0]
                elif expr[1] == ('&', expr[0], expr[2]):
                    return expr[0]
            elif expr[0] == '|':
                if expr[1] == ('&', expr[0], expr[2]):
                    return expr[0]
                elif expr[1] == ('|', expr[0], expr[2]):
                    return expr[0]
        return expr

    def apply_negative_absorption(expr):
        if isinstance(expr, tuple):
            if expr[0] == '&':
                if expr[1] == ('|', ('~', expr[0]), expr[2]):
                    return expr[2]
                elif expr[1] == ('&', ('~', expr[0]), expr[2]):
                    return expr[2]
            elif expr[0] == '|':
                if expr[1] == ('&', ('~', expr[0]), expr[2]):
                    return expr[0]
                elif expr[1] == ('|', ('~', expr[0]), expr[2]):
                    return expr[0]
        return expr

    new_args = []
    for arg in args:
        new_arg = apply_absorption(arg)
        new_arg = apply_negative_absorption(new_arg)
        new_args.append(new_arg)
    return new_args

