    """Render pieces as JSON."""
    import json
    return json.dumps(pieces)

def render_xml(pieces):
    """Render pieces as XML."""
    import xml.etree.ElementTree as ET
    root = ET.Element("root")
    for piece in pieces:
        ET.SubElement(root, "piece").text = piece
    return ET.tostring(root, encoding='unicode')

