def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    for arg_name, arg_value in args.items():
        if not isinstance(arg_value, str):
            raise TypeError(f"Value of argument '{arg_name}' must be a string")

        if len(arg_value) > 100:
            raise ValueError(f"Value of argument '{arg_name}' is longer than 100 characters")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_name in self.choices:
            if arg_value not in self.choices[arg_name]:
                raise ValueError(f"Invalid value for argument '{arg_name}': {arg_value}. Available choices are {self.choices[arg_name]}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """

    if not args:
        raise ValueError("No arguments provided")

    min_val = getattr(self, 'min_value', None)
    max_val = getattr(self, 'max_value', None)

    if min_val is None and max_val is None:
        raise ValueError("Neither min_value nor max_value is set")

    for arg in args:
        if min_val is not None and arg < min_val:
            raise ValueError(f"Argument {arg} is less than the minimum value {min_val}")
        if max_val is not None and arg > max_val:
            raise ValueError(f"Argument {arg} is greater than the maximum value {max_val}")

    return args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for key, value in args.items():
        if key.startswith('control_'):
            control_args[key] = value
        elif key.startswith('nested_'):
            nested_args[key] = value
        else:
            custom_args[key] = value

    return control_args, nested_args, custom_args

